def build():
    rnd = random.Random(1988)
    out = []
    for i, (nivel, tema, perg, cor, errs, expl, fonte) in enumerate(Q):
        assert len(errs) == 3, perg
        alts = [cor] + errs
        rnd.shuffle(alts)
        out.append(dict(id=f"q{i+1:03d}", nivel=nivel, tema=tema, pergunta=perg, alternativas=alts,
                        correta=alts.index(cor), explicacao=expl, fonte=fonte))
    temas = sorted({x["tema"] for x in out})
    with open(OUT, "w", encoding="utf-8") as f:
        json.dump({"versao": 1, "quizzes": [{"id": t, "titulo": t} for t in temas], "perguntas": out}, f, ensure_ascii=False, indent=1)
    from collections import Counter
    print(len(out), Counter(x["nivel"] for x in out), Counter(x["tema"] for x in out))
build()
